import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"既濟","description":"高岛易断 - 既濟","frontmatter":{"title":"既濟","description":"高岛易断 - 既濟"},"headers":[],"relativePath":"zh/classics/takashima/063.md","filePath":"zh/classics/takashima/063.md"}'),i={name:"zh/classics/takashima/063.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="既濟" tabindex="-1">既濟 <a class="header-anchor" href="#既濟" aria-label="Permalink to “既濟”">​</a></h1><h2 id="既濟-1" tabindex="-1">既濟 <a class="header-anchor" href="#既濟-1" aria-label="Permalink to “既濟”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>既济：亨小，利贞，初吉终乱。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“济”者，渡也，“既”者，尽也，万事皆济，故曰《既济》。卦取《坎》《离》，坎水润下，《离》火炎上，相交为用，阴阳和会，百务就理，无有不亨。然《既济》之亨，亨犹其小者耳，故曰“亨小”。在处既济者，犹当勿侈其亨，在励其贞，贞于初，亦贞于终，斯有吉无乱矣，故曰“利贞”。若不能长保其贞，则亨通未久，危乱随之，故曰“初吉，终乱”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>水在火上，既济。君子以思患而豫防之。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>水性润下，火性炎上，水在火上，火在水下，二者相资为用，得以成《既济》之功也。君子玩其象，而凛凛焉，不以《既济》为可恃，更以《既济》为可危。坎险在外，防患之象；《离》明在内，预思之象。祸每生于不测，害即伏于既安，预时而防之，则可以保其“初吉”，即可以戢其“终乱”，故曰“君子以思患而豫防之”。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运途全盛，盛极必衰，须防后患。</p><p>○　问营商：目下货物，得时得价，正当满足，须留后步。</p><p>○　问功名：居高思危，得防其终。</p><p>○　问战征：大难既平，大险既定，战胜功成，还宜图始保终，毋贻后患。</p><p>○　问家宅：大厦既成，苟完苟合，贻谋孔远。</p><p>○　问婚姻：有好合百年之兆。</p><p>○　问疾病：大病既痊，更宜自保。</p><p>○　问讼事：毋再涉讼。</p><p>○　问六甲：春夏生女，秋冬生男。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>《既济》爻义，大略与《泰》同。《泰》下卦三爻，为《泰》中之《泰》，上卦三爻，为《泰》中之《否》，《既济》亦然。其所以分内外者，《离》为明，《坎》为险，犹《泰》以《乾》为有余，《坤》为不足也。《既济》初爻，以济渡取义，故有曳轮濡尾之象，《坎》为轮，为曳，初为尾。“曳其轮”者，曳之前进，是用力而求济也。按《诗》“济盈不濡轨，始济而濡及马尾”，言济之难也，然尾虽濡而曳不倦，曳者济矣。初居济之始，力求其济如此，故“无咎”也，《象传》即以无咎释之。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：运未脱险，当自奋勉，可以无咎。</p><p>○　问营商：初次经营，跋涉多艰，前而不止，虽危得济，无咎。</p><p>○　问功名：先难后获。</p><p>○　问战征：虽有车脱马蹶之危，一鼓而进，当必可获胜也。</p><p>○　问家宅：初次迁居，虽此宅或轮奂不美，或首尾不完，居之无咎。</p><p>○　问婚姻：火为水妃，初聘则吉。</p><p>○　问疾病：初病，虽危无咎。</p><p>○　问六甲：初胎生女。</p><p>○　问失物：物已沾水，当就车中觅之，可得。</p><p>○　问行人：在途，稍有水灾，无咎。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治二十一年，缙绅某来，请占气运，筮得《既济》之《蹇》。</p><p>断曰：“轮”，车轮，涉水之具；“尾”，马尾，为水所濡也。是为曳轮济水，马尾被濡，盖言初济之难。初能用力求济，终得无咎，足见人当涉险之时，奋力脱险，险无不可济也。今贵下占时运，得《既济》初爻，知贵下方今盛运已来，时安身泰，但险难初脱，尚小有灾害，可无患也。明后二三年，犹须谨戒，四年后，则吉福来临，全盛有庆，无往不利。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>火为水妃，故二《离》象妇。“茀”，车蔽也。《尔雅》“舆革，前谓之艰，后谓之茀；竹，前谓之御，后谓之蔽”，曰“弗”，曰“蔽”，以竹革而异也。《诗》则统谓之茀，“硕人翟茀以朝”。《孔疏》云：妇人乘车不露，车之前后，皆设障以自隐蔽，谓之茀，丧弗者，失其所蔽也。二当临济之时，驱车前进，车在前，弗在后，中途丧弗，停车而逐，将有欲济而不及者矣，故示之以“勿逐”。“七日得”者，得犹复也。阴阳之数，至七而复，一卦六爻，循环往复，自二后至七，又值二爻，故不过七日而自得也。《象传》以“中道”释之，日辰十二，七日正当中也。丧茀者，或云二乘车适五，四当其前，四《坎》为盗，是窃茀者也。其说亦通。茀，《释文》：茀首饰。按《诗》屡言茀，皆作车蔽，且初曰曳轮，二日车茀，象正相合，当作车蔽。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：小小得失，切勿介意，方得脱大难，成大功也。</p><p>○　问营商：有失而复得之象。</p><p>○　问功名：七年内，定可复职。</p><p>○　问战征：中途被劫，丧其辎重，七日内，必获胜仗。</p><p>○　问婚姻：早则七月，迟则七年，可复团聚。</p><p>○　问家宅：其宅被人居，七年后，即可归还原主。</p><p>○　问疾病：七日必愈。</p><p>○　问失物：不久可得。</p><p>○　问六甲：七日内可产，生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>一友访余山庄，谈及某贵显，曰：贵显以未赐勋章为憾，请为一占。筮得《既济》之《需》。</p><p>断曰：茀为车蔽，言妇人乘车，设之所以自蔽也，丧茀则失其所蔽矣。“勿逐”者，谓区区小失，不必追逐，不久自可后得，喻言人当建大功，立大业，琐屑微物，得丧本不关荣辱也。今为某贵显占勋章，得此爻象，爻象所言，显然明示，劝贵显不必忧虑。“七日得”者，谓不久定可荣膺宠赐也。后友人复来曰：占筮甚灵，某贵显已得宠赐勋章，爻辞之言，恰如为某贵显特设者也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“高宗”，殷中兴之主；“鬼方”，西羌国名。按《竹书纪年》，武丁三十二年伐鬼方，次于荆，三十四年，克鬼方，氏羌来宾，即“高宗伐鬼方，三年克之”，实事也。《既济》爻象，初二皆在济中，至三始济，故取三年克鬼方以为况。高宗贤主，鬼方小国，六师所加，三年乃克，师亦惫矣，以喻济《坎》之难如此。天下之事，每以艰难得之，安乐失之，当其始，数载经营而不足，其后一旦败坏而有余；而其弊皆由于远君子而近小人也，故戒曰“勿用小人”，处《既济》者，所当凛凛焉。《师》上爻曰，“开国承家，小人勿用”，与此爻辞，意正同。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：忍苦耐劳，所谋必成。</p><p>○　问营商：数载经营，方可获利。</p><p>○　问功名：辛苦而成。</p><p>○　问战征：劳师久征，所攻虽得，然亦惫矣。</p><p>○　问婚姻：三年内可完配。</p><p>○　问家宅：此宅阴象太重，三年后，方可居住。</p><p>○　问疾病：此病一时无恙，三年内，必难保全。</p><p>○　问讼事：三年可了，防小人又复生事，宜戒。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>某商人来，请占谋事成否，筮得《既济》之《屯》。</p><p>断曰：“高宗伐鬼方”，历三年之久，而乃得克之，以喻三爻处内卦之终，历初二之难，而始得济之，其象正同，观此即可知谋事之非易易也。今君占谋事成否，得此爻辞，知君所谋之事，一时必难就绪，早则三月，迟则三年，方可合议成就。成后二年，定有大来之吉，但其事与君子合谋，自有利益，与小人合谋，必致败坏，君其尤当注意焉。</p><p>三十年，杉浦重刚氏来，曰：足尾矿毒事件，纷纷滋议，朝野骚然，请占其结果如何？筮得《既济》之《屯》。</p><p>断曰：按九三《艮》爻，《艮》为鬼门，故曰“鬼方”。三居《坎》《离》之间，《坎》为毒，为疾，《离》为大腹，三与上应，三至上三爻，故曰“三年”。“克之”者，治之也。象为腹受其毒以至死亡，其毒实起于《离》火，出自坎水，非一日矣。爻辞所云“高宗伐鬼方”者，“鬼方”，喻言其地之险也。高宗贤主，喻言必有能人治之也。今占足尾矿毒，得此爻象，按足尾铜山，每年出铜一千二百万斤，其价不下三百万元，政府收税，得十五万元，矿局夫役，约有一万八千人数，皆赖此为生活，是我国矿山之最大者也。毒由矿铜出丹矾，丹矾有毒，毒入河流，平时未闻其害，因洪水浸田，其毒遂滋。原洪水冲决，由于堤防不固，堤防之害，咎归土木局，至土木局修筑堤防，必需经费，其责又归大藏省。今矿毒事件，纷议未有的论，多为小人从中扇惑所致，恐此案亦将亘三年之久乎？必于此事无甚关系者，不许干涉，谓之“小人勿用”；修筑堤防，以杜坎水之害，此案自得终局矣。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>按：“繻”为采绘，“袽”为敝衣。四处内外卦之交，出《离》入坎，繻有文明之象，盖取诸《离》；袽为败衣，《坎》为破，盖取诸《坎》。言四当《既济》之盛，衣冠济济，文物声名，焕然一新，然天命靡常，盛倏为衰，新倏成故，若不因时弥缝，曾不几时，立成败坏，犹是绘采之华裳，未几而为敝败之残絮矣，故曰“繻有衣袽。”《既济》，由《乾》《坤》二五相易而来，“终日戒”者，即《乾》“终日乾乾，夕惕若”之意，当《既济》而益励危心，其戒慎无已时也，故曰“终日戒”。《传》释以“有所疑”，《坎》为疑，疑者，未然而忧其或然，亦戒也。“繻”，王弼谓宜作濡，衣袽谓以敝衣塞舟漏也。王弼之解，强从济字取义，谓济必有舟，舟或有漏则濡，濡则敝衣塞之。于爻辞“繻有衣袽”一语，添生枝节，自圆其说，未免矫强。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：运当全盛，然不预防，衰即立至，所宜谨戒。</p><p>○　问营商：如舟行，中流舟漏，急宜补修。</p><p>○　问功名：有忽赐忽褫之惧。</p><p>○　问战征：夺帜易帜，胜当虑败，所贵临事而惧。</p><p>○　问婚姻：古人多以衣服比夫妇，为不可喜新而弃旧也。</p><p>○　问疾病：是老弱之症也。</p><p>○　问六甲：生男。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>一日西村舍三氏来，曰：予奉职土木局长，数年来为治水巡回全国，已三次矣。溯自维新以前，各藩自保疆土，堤防山林，各有禁令，是以林木畅茂，土脉坚固，无堤防溃决之患也；维新以降，政令一变，山阜陵谷，无不开垦，泥土流出，壅塞河道，以致河流不通，溢出堤上。洪水泛滥，为灾非浅，乏奠平之策，子幸一筮，以示处理之方。筮得《既济》之《革》。</p><p>断曰：爻辞“繻有衣袽”，“繻”作濡，为濡漏之象，“衣袽”，敝衣，为塞漏之用。“终日戒”者，为危险之至，非一时可济，须终日防备也。舟漏虽小，而治水之法，爻已显示其象矣。足下占治水之方，得此爻辞，所谓危者防之，漏者塞之。爻曰“衣袽”，第即一物以喻之而已，或用沙土，或用木石，皆可以“衣袽”例之，因地制宜，由小及大，皆在足下酌行之耳。“终日戒”，三字，最为切要，所当刻刻预防，不可稍懈，有危心无危地也。治水之道，无过于此。</p><p>知人阪田春雄氏，尝奉命赴澳国博览会，余一日访其家，其母语余曰：前有电信，报告归期，今愆期未归，并无后电，心甚忧之。请余一占，筮得《既济》之《革》。</p><p>断曰：此卦上《坎》下《离》，《离》南《坎》北，今四爻出《离》入坎，是船已过赤道，而在北洋之象。依爻辞，知有行舟破漏之患，实为可虑，然《离》阴变为《坎》阳，生命无害。又进一爻，则五爻之阳，变而为阴，是水变为地，即全身上陆之象，其免难也必矣。时其家有洋学生三人，闻此断语，窃相诽笑。余曰：《易》理甚妙，非诸君所知也，诸君不信，待春雄君归时，可知灵验矣。后数日，春雄氏归，曰船抵赤道以北，为暗礁所伤，是以着港，致迟延也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五与二相应，犹东与西相对，五为君，二为臣。东邻为君，是纣之国中，西邻为臣，是文王之国中也。按纣都在东，岐周在西，东邻西邻，郑谓殷周是也。《离》为牛，《坎》为豕，杀牛而凶，不如杀豕受福，喻言奢而慢，不如俭而敬也。上卦处《既济》之后，下卦当甫济之时，殷天子祭用太牢，故杀牛；周西伯不得用牛，用豕，故为禴。当时殷道已衰，时为《既济》；周德方新，时为甫济。《既济》者，时已去，甫济者，时方来。已去不复也，方来者未有已也，则杀牛不足侈，而禴祭大可恃，故曰“东邻杀牛，不如西邻之禴祭，实受其福”。九五阳爻，阳为实，五体《乾》，《乾》为福，《象传》以“吉大来”释之。《泰》曰“小往大来，吉亨”，自外而内曰来，卦以二五相易，为《乾》成《泰》，谓福自《乾》来也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：已盛则退，方盛则进，宜保俭约，毋侈奢华，吉凶皆由自取也。</p><p>○　问战征：盛气在西，宜顺天修德，不宜暴兵耀武。</p><p>○　问营商：合伙同业，殷富者亦奢，不如俭约者，实获其利也。</p><p>○　问功名：已成者宜慎，未成者大可望也。</p><p>○　问婚姻：宜就西邻订姻，吉。</p><p>○　问家宅：宅以西首为吉。</p><p>○　问疾病：宜祷。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>横滨辨天通橘屋者，余之所知也，其邻家，有岩井屋某，专售西洋家具。明治元年，余因橘屋介绍，卖与木材，价值数千元，岂知彼阳饰富裕，内实贫困，阅数日不偿其价，余乃忧之。以一占决之，筮得《既济》之《明夷》。</p><p>断曰：爻言“东邻杀牛，不如西邻之禴祭”受福，卦以九五为东邻，以六四为西邻，五为主爻，五与二应，是主不如应也。今就所占论之，则以岩井之卖主为东邻，以橘屋之介绍为西邻，如此疑橘屋，有于中取利矣，我将向橘屋索价，橘屋必不能辞责。以橘屋当西邻，爻位属《离》，《离》火也；卖者为木材，木以生火，火得旺势，则坎水受煎，东邻亦不能不出而偿价也；且《离》为女，可着女人而往索之。后余果与橘屋妻女相谋，乃得受值。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上为首，初为尾，是首尾相接也。上处《既济》之极，反之即《未济》，已然者甫能过，未然时相待，进而不已，身虽未溺，首先犯焉，故曰“濡其首”。夏殷之盛，未几而坏于桀纣，文武之兴，未几而降为幽厉，所谓治日少而乱日多者，古今有同慨焉，故曰“厉”。《象传》曰“何可久”，所以戒之者深矣。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：好运已过，深为可危，宜慎。</p><p>○　问战征：上处坎险之极，上为首，恐首将有不利。</p><p>○　问营商：头番买卖，必难获利。</p><p>○　问功名：可许夺元。</p><p>○　问婚姻：元配有灾，续弦无咎。</p><p>○　问家宅：此宅长房不利。</p><p>○　问讼事：防首领难保。</p><p>○　问疾病：患在首面，可危。</p><p>○　问六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某来，请占行运，筮得《既济》之《家人》。</p><p>断曰：上处《既济》之终，不保其终，《既济》即转而为《未济》。上为首，是首先濡矣；喻言人生在世，前运既过，后运将来，既过者其险已平，将来者其险正多。知足下方今，正当交运之时，前运大佳，后运犹当谨慎，可以出险脱危。</p>',112)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
